                    })
                }



            }
        } catch (error) {
            reject(error)
        }
    })
}
let handleForgotPassword = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            if (!data.id || !data.token || !data.password) {
                resolve({
                    errCode: 1,
                    errMessage: 'Missing required parameter!'
                })
            } else {
                let user = await db.User.findOne({
                    where: {
                        id: data.id,
                        usertoken: data.token
                    },
                    attributes: {
                        exclude: ['password']
                    },
                    raw: false
                })

                if (user) {
                    user.password = await hashUserPasswordFromBcrypt(data.password);
                    user.usertoken = "";

                    await user.save();

                }
                resolve({
                    errCode: 0,
                    errMessage: 'ok'
                })
            }
        } catch (error) {
            reject(error)
        }
    })
}
let checkPhonenumberEmail = (data) => {
    return new Promise(async (resolve, reject) => {
        try {
            let phone = await db.User.findOne({
                where: { phonenumber: data.phonenumber }
            })
            let email = await db.User.findOne({
                where: { email: data.email }
            })
            if (phone) {
                resolve({
                    isCheck: true,
                    errMessage: "Số điện thoại đã tồn tại"
                })
            }
            if (email) {
                resolve({
                    isCheck: true,
                    errMessage: "Email đã tồn tại"
                })
            }

            resolve({
                isCheck: false,
                errMessage: "Hợp lệ"
            })

        } catch (error) {
            reject(error)
        }
    })
}
module.exports = {
    handleCreateNewUser: handleCreateNewUser,
