        errCode: 503,
        status: 'unavailable',
        database: 'disconnected',
        errMessage: 'Không thể kết nối MySQL.'
      });
    }
  });
  initWebRoutes(app);
  app.use((req, res) => res.status(404).json({
    errCode: 404,
    errMessage: 'API không tồn tại.'
  }));
  app.use((error, req, res, next) => {
    if (res.headersSent) return next(error);
    const status = error.status || 500;
    if (status >= 500) console.error('Request failed:', error.name);
    res.status(status).json({
      errCode: status,
      errMessage: status === 500 ? 'Lỗi máy chủ. Vui lòng thử lại.' : error.message
    });
  });
  return app;
}
module.exports = {
  createApp,
  allowedOrigins
};
