          as: 'brandData'
        });
        Allcode.hasMany(models.Product, {
          foreignKey: 'statusId',
          as: 'statusData'
        });
      }
      if (models.Blog) {
        Allcode.hasMany(models.Blog, {
          foreignKey: 'subjectId',
          as: 'subjectData'
        });
      }
      if (models.TypeVoucher) {
        Allcode.hasMany(models.TypeVoucher, {
          foreignKey: 'typeVoucher',
