  Op
} = require("sequelize");
const {
  createCommerceService
} = require('./commerceService');
const {
  resultOf,
  fail,
  positiveInteger,
  money
} = require('../utils/commerce');
const commerce = createCommerceService(_index.default);
const decodeImage = image => image == null ? '' : Buffer.from(image).toString('utf8');
function dynamicSort(property) {
  var sortOrder = 1;
  if (property[0] === "-") {
    sortOrder = -1;
    property = property.substr(1);
  }
  return function (a, b) {
    /// sap xep tang dan
    var result = a[property] < b[property] ? -1 : a[property] > b[property] ? 1 : 0;
    return result * sortOrder;
  };
}
function dynamicSortMultiple() {
  var props = arguments;
  return function (obj1, obj2) {
    var i = 0,
      result = 0,
      numberOfProperties = props.length;
    /* try getting a different result from 0 (equal)
     * as long as we have extra properties to compare
     */
    while (result === 0 && i < numberOfProperties) {
      result = dynamicSort(props[i])(obj1, obj2);
      i++;
    }
    return result;
  };
}
const createNewProduct = data => resultOf(async () => {
  if (!data.name || !data.categoryId || !data.brandId || !data.image || !data.nameDetail || !data.sizeId) fail('Vui lòng nhập đầy đủ thông tin sản phẩm.');
  const originalPrice = money(data.originalPrice),
    discountPrice = money(data.discountPrice);
  if (discountPrice > originalPrice) fail('Giá bán không được vượt quá giá gốc.');
  return commerce.transaction(async tx => {
    const product = await _index.default.Product.create({
      name: data.name,
      contentHTML: data.contentHTML,
      contentMarkdown: data.contentMarkdown,
      statusId: 'S1',
      categoryId: data.categoryId,
      madeby: data.madeby,
      material: data.material,
      brandId: data.brandId,
      view: 0
    }, {
      transaction: tx
    });
    const detail = await _index.default.ProductDetail.create({
      productId: product.id,
      description: data.description,
      originalPrice,
      discountPrice,
      nameDetail: data.nameDetail
    }, {
      transaction: tx
    });
    await _index.default.ProductImage.create({
      productdetailId: detail.id,
      image: data.image
    }, {
      transaction: tx
    });
    await _index.default.ProductDetailSize.create({
      productdetailId: detail.id,
      width: data.width,
      height: data.height,
      sizeId: data.sizeId,
      weight: data.weight
    }, {
      transaction: tx
    });
    return {
      errCode: 0,
      errMessage: 'ok',
      data: product
    };
  });
});
