const deleteProductDetail = data => resultOf(async () => {
  if (!positiveInteger(data.id)) fail('Mã chi tiết sản phẩm không hợp lệ.');
  return commerce.transaction(async tx => {
    const detail = await _index.default.ProductDetail.findByPk(data.id, {
      transaction: tx,
      raw: false
    });
    if (!detail) fail('Chi tiết sản phẩm không tồn tại.', 2);
    const variants = await _index.default.ProductDetailSize.findAll({
      where: {
        productdetailId: data.id
      },
      transaction: tx,
      raw: true
    });
    await commerce.lockVariants(variants.map(variant => ({
      productId: variant.id
    })), tx);
    for (const variant of variants) await assertUnusedVariant(variant.id, tx);
    await _index.default.ProductImage.destroy({
      where: {
        productdetailId: data.id
      },
      transaction: tx
    });
    await _index.default.ProductDetailSize.destroy({
      where: {
        productdetailId: data.id
      },
      transaction: tx
    });
    await detail.destroy({
      transaction: tx
    });
    return {
      errCode: 0,
      errMessage: 'ok'
    };
  });
});
async function assertUnusedVariant(id, tx) {
  if ((await _index.default.ReceiptDetail.count({
    where: {
      productDetailSizeId: id
    },
    transaction: tx
  })) || (await _index.default.OrderDetail.count({
    where: {
      productId: id
    },
    transaction: tx
  })) || (await _index.default.ShopCart.count({
    where: {
      productdetailsizeId: id
    },
    transaction: tx
  })) || (await commerce.activeSessions(tx)).some(session => session.checkout.lines.some(line => Number(line.productId) === Number(id)))) {
    fail('Không thể xóa biến thể đang có trong giỏ hàng, phiếu nhập hoặc đơn hàng. Hãy ngừng kinh doanh sản phẩm thay vì xóa.', 2);
  }
}
