        where: {
          id: line.productId
        },
        ...options(tx),
        raw: true
      });
      const detail = await db.ProductDetail.findOne({
        where: {
          id: variant.productdetailId
        },
        ...options(tx),
        raw: true
      });
      const product = detail && (await db.Product.findOne({
        where: {
          id: detail.productId,
          statusId: 'S1'
        },
        ...options(tx),
        raw: true
      }));
      if (!product) fail('Sản phẩm đã ngừng kinh doanh.', 2);
      line.realPrice = money(detail.discountPrice);
      line.name = `${product.name} - ${detail.nameDetail}`;
      subtotal += line.realPrice * line.quantity;
