"use strict";

const db = require('../models');
const {
  Op
} = require('sequelize');
const {
  createCommerceService
} = require('./commerceService');
const {
  positiveInteger,
  money,
  fail,
  resultOf,
  voucherIsActive
} = require('../utils/commerce');
const commerce = createCommerceService(db);
const ok = data => ({
  errCode: 0,
  errMessage: 'ok',
  ...data
});
const pagination = (data = {}) => Number(data.limit) > 0 ? {
  limit: Math.min(100, Number(data.limit)),
  offset: Math.max(0, Number(data.offset) || 0)
} : {};
const typeInclude = () => [{
  model: db.Allcode,
  as: 'typeVoucherData',
  attributes: ['value', 'code']
}];
const voucherInclude = () => [{
  model: db.TypeVoucher,
  as: 'typeVoucherOfVoucherData',
  include: typeInclude()
}];
const find = async (model, id, options = {}) => {
  if (!positiveInteger(id)) fail('Mã dữ liệu không hợp lệ.');
  const row = await model.findByPk(id, options);
  if (!row) fail('Dữ liệu không tồn tại.', 2);
  return row;
};
const typeValues = data => {
  if (!['percent', 'money'].includes(data.typeVoucher)) fail('Loại giảm giá không hợp lệ.');
  const result = {
    typeVoucher: data.typeVoucher,
    value: money(data.value),
    minValue: money(data.minValue),
    maxValue: money(data.maxValue)
  };
  if (result.typeVoucher === 'percent' && (result.value < 1 || result.value > 100)) fail('Phần trăm giảm giá phải từ 1 đến 100.');
  if (result.typeVoucher === 'money' && !(result.maxValue || result.value)) fail('Giá trị giảm giá phải lớn hơn 0.');
  return result;
};
const voucherValues = async (data, tx) => {
  if (typeof data.codeVoucher !== 'string' || !data.codeVoucher.trim() || !positiveInteger(data.amount) || !positiveInteger(data.typeVoucherId)) fail('Thông tin voucher không hợp lệ.');
  const date = value => /^\d+$/.test(String(value)) ? Number(value) : new Date(value).getTime();
  const from = date(data.fromDate),
    to = date(data.toDate);
  if (!Number.isFinite(from) || !Number.isFinite(to) || from > to) fail('Thời gian sử dụng voucher không hợp lệ.');
  await find(db.TypeVoucher, data.typeVoucherId, {
    transaction: tx,
    raw: true
  });
  const duplicate = await db.Voucher.findOne({
    where: {
      codeVoucher: data.codeVoucher.trim(),
      ...(data.id ? {
        id: {
          [Op.ne]: data.id
        }
      } : {})
    },
    transaction: tx,
    raw: true
  });
  if (duplicate) fail('Mã voucher đã tồn tại.', 2);
  return {
    codeVoucher: data.codeVoucher.trim(),
    amount: Number(data.amount),
    typeVoucherId: data.typeVoucherId,
    fromDate: String(from),
    toDate: String(to)
  };
};
const decorate = async voucher => {
  voucher.usedAmount = await db.VoucherUsed.count({
    where: {
      voucherId: voucher.id,
      status: 1
    }
  });
  return voucher;
};
const createNewTypeVoucher = data => resultOf(async () => ok({
  data: await db.TypeVoucher.create(typeValues(data))
}));
const getDetailTypeVoucherById = id => resultOf(async () => ok({
  data: await find(db.TypeVoucher, id, {
    include: typeInclude(),
    raw: true,
    nest: true
  })
}));
const getAllTypeVoucher = data => resultOf(async () => {
  const rows = await db.TypeVoucher.findAndCountAll({
    ...pagination(data),
    include: typeInclude(),
    raw: true,
    nest: true
  });
  return ok({
    data: rows.rows,
    count: rows.count
  });
});
const getSelectTypeVoucher = () => resultOf(async () => ok({
  data: await db.TypeVoucher.findAll({
    include: typeInclude(),
    raw: true,
    nest: true
  })
}));
const updateTypeVoucher = data => resultOf(async () => {
  const values = typeValues(data);
  const row = await find(db.TypeVoucher, data.id, {
    raw: false
  });
  Object.assign(row, values);
  await row.save();
  return ok();
});
